-- Create syntax for TABLE 'association_business_situation'
CREATE TABLE `association_business_situation` (
                                                  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
                                                  `row_num` int(11) NOT NULL COMMENT '行号 | 同一批次数据从1开始递增',
                                                  `unif_soci_cred_code` varchar(32) NOT NULL COMMENT '企业统一社会信用代码',
                                                  `tot_incm_abop` decimal(25,8) DEFAULT NULL COMMENT '总收入_期初数（万元）',
                                                  `tot_incm_aotc` decimal(25,8) DEFAULT NULL COMMENT '总收入_本期发生额（万元）',
                                                  `tot_incm_aeop` decimal(25,8) DEFAULT NULL COMMENT '总收入_期末数（万元）',
                                                  `oper_leas_busi_incm_abop` decimal(25,8) DEFAULT NULL COMMENT '经营租赁业务收入_期初数（万元）',
                                                  `oper_leas_busi_incm_aotc` decimal(25,8) DEFAULT NULL COMMENT '经营租赁业务收入_本期发生额（万元）',
                                                  `oper_leas_busi_incm_aeop` decimal(25,8) DEFAULT NULL COMMENT '经营租赁业务收入_期末数（万元）',
                                                  `fnl_busi_incm_abop` decimal(25,8) DEFAULT NULL COMMENT '融资租赁业务收入_期初数（万元）',
                                                  `fnl_busi_incm_aotc` decimal(25,8) DEFAULT NULL COMMENT '融资租赁业务收入_本期发生额（万元）',
                                                  `fnl_busi_incm_aeop` decimal(25,8) DEFAULT NULL COMMENT '融资租赁业务收入_期末数（万元）',
                                                  `intr_incm_abop` decimal(25,8) DEFAULT NULL COMMENT '利息收入_期初数（万元）',
                                                  `intr_incm_aotc` decimal(25,8) DEFAULT NULL COMMENT '利息收入_本期发生额（万元）',
                                                  `intr_incm_aeop` decimal(25,8) DEFAULT NULL COMMENT '利息收入_期末数（万元）',
                                                  `fee_incm_abop` decimal(25,8) DEFAULT NULL COMMENT '费用收入_期初数（万元）',
                                                  `fee_incm_aotc` decimal(25,8) DEFAULT NULL COMMENT '费用收入_本期发生额（万元）',
                                                  `fee_incm_aeop` decimal(25,8) DEFAULT NULL COMMENT '费用收入_期末数（万元）',
