                                                      `corp_inct_aotc` decimal(25,8) DEFAULT NULL COMMENT '企业所得税_发生(万元)',
                                                      `corp_inct_aeop` decimal(25,8) DEFAULT NULL COMMENT '企业所得税_期末(万元)',
                                                      `oth_tax_abop` decimal(25,8) DEFAULT NULL COMMENT '其他税金_期初(万元)',
                                                      `oth_tax_aotc` decimal(25,8) DEFAULT NULL COMMENT '其他税金_发生(万元)',
                                                      `oth_tax_aeop` decimal(25,8) DEFAULT NULL COMMENT '其他税金_期末(万元)',
                                                      `oty_taxp_amt_abop` decimal(25,8) DEFAULT NULL COMMENT '历年税金_期初(万元)',
                                                      `oty_taxp_amt_aotc` decimal(25,8) DEFAULT NULL COMMENT '历年税金_发生(万元)',
                                                      `oty_taxp_amt_aeop` decimal(25,8) DEFAULT NULL COMMENT '历年税金_期末(万元)',
                                                      `ofbl_amt_abop` decimal(25,8) DEFAULT NULL COMMENT '表外业务_期初(万元)',
                                                      `ofbl_amt_aotc` decimal(25,8) DEFAULT NULL COMMENT '表外业务_发生(万元)',
                                                      `ofbl_amt_aeop` decimal(25,8) DEFAULT NULL COMMENT '表外业务_期末(万元)',
                                                      `report_instance_id` varchar(64) NOT NULL COMMENT '报表实例ID | UUID',
                                                      `report_instance_period` varchar(24) NOT NULL COMMENT '报表周期 | YYYYQQ格式',
                                                      `batch_no` varchar(4) NOT NULL COMMENT '批次号 | 0000-9999',
                                                      `version` varchar(128) DEFAULT NULL COMMENT '版本号 | 周期+版本',
                                                      `op` varchar(16) NOT NULL DEFAULT 'insert' COMMENT '操作标识 | insert/update',
                                                      `report_time` datetime DEFAULT NULL COMMENT '上报时间',
                                                      `write_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '入库时间',
                                                      `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                                      `create_by` bigint(20) DEFAULT NULL COMMENT '创建人id',
                                                      `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                                      `update_by` bigint(20) DEFAULT NULL COMMENT '更新人id',
                                                      `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除标识',
                                                      PRIMARY KEY (`id`),
                                                      KEY `idx_reportinstanceid` (`report_instance_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='实体经济服务数据表';

-- Create syntax for TABLE 'association_external_financing'
CREATE TABLE `association_external_financing` (
                                                  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
                                                  `row_num` int(11) NOT NULL COMMENT '行号 | 同一批次数据，行号1开始进行递增（确认数据问题快速定位）',
                                                  `unif_soci_cred_code` varchar(32) NOT NULL COMMENT '企业统一社会信用代码',
                                                  `onum` varchar(128) DEFAULT NULL COMMENT '序号',
                                                  `loan_bal` decimal(25,8) DEFAULT NULL COMMENT '借款余额 | 单位：万元',
                                                  `fin_busi_type_code` varchar(64) DEFAULT NULL COMMENT '融资业务类型 | 数据字典：EVT00052',
                                                  `cptl_prov` varchar(64) DEFAULT NULL COMMENT '资金提供方',
                                                  `fin_intr` decimal(21,8) DEFAULT NULL COMMENT '融资利率',
                                                  `fin_loan_date` date DEFAULT NULL COMMENT '融资借款日期',
                                                  `fin_matu_date` date DEFAULT NULL COMMENT '融资到期日期',
                                                  `report_instance_id` varchar(64) NOT NULL COMMENT '报表实例编号 | 格式：UUID',
                                                  `report_instance_period` varchar(24) NOT NULL COMMENT '报表实例周期 | 格式：YYYYQQ',
                                                  `batch_no` varchar(4) NOT NULL COMMENT '批次号 | 4位字符，根据月报/季报/年报的上报周期，同期数据重复上传时从0000开始递增，9999后重置',
                                                  `version` varchar(128) DEFAULT NULL COMMENT '版本号 | 报表实例周期+版本号',
                                                  `op` varchar(16) NOT NULL DEFAULT 'insert' COMMENT '操作标识 | 值域：insert/update',
                                                  `report_time` datetime DEFAULT NULL COMMENT '上报时间 | 数据文件上传时间',
                                                  `write_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '写入时间 | 数据库写入时间',
                                                  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                                  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人id',
                                                  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                                  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人id',
                                                  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除标识',
                                                  PRIMARY KEY (`id`),
                                                  KEY `idx_reportinstanceid` (`report_instance_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='金融局报送-对外融资信息清单表';

-- Create syntax for TABLE 'association_main_business'
CREATE TABLE `association_main_business` (
                                             `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键id',
                                             `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                             `create_by` bigint(20) DEFAULT NULL COMMENT '创建人id',
                                             `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                             `update_by` bigint(20) DEFAULT NULL COMMENT '更新人id',
                                             `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除，0-未删除',
                                             `row_num` int(11) NOT NULL COMMENT '行号',
                                             `report_instance_id` varchar(64) NOT NULL COMMENT '报表实例编号',
                                             `report_instance_period` varchar(24) NOT NULL COMMENT '报表实例周期',
                                             `batch_no` varchar(4) NOT NULL DEFAULT '' COMMENT '批次号',
                                             `version` varchar(128) DEFAULT NULL COMMENT '版本号',
                                             `op` varchar(16) NOT NULL COMMENT '操作标识',
                                             `report_time` datetime DEFAULT NULL COMMENT '上报时间',
                                             `write_time` timestamp NOT NULL COMMENT '写入数据库时间',
                                             `unif_soci_cred_code` varchar(32) NOT NULL COMMENT '企业统一社会信用代码',
                                             `onum` varchar(128) DEFAULT NULL COMMENT '序号',
                                             `agmt_name` varchar(255) DEFAULT NULL COMMENT '合同名称',
                                             `agmt_no` varchar(255) DEFAULT NULL COMMENT '合同编号',
                                             `agmt_sign_date` date DEFAULT NULL COMMENT '合同签订日期',
                                             `agmt_matu_date` date DEFAULT NULL COMMENT '协议到期日期',
                                             `agmt_type_code` varchar(6) DEFAULT NULL COMMENT '合同类型',
                                             `lasd_type` varchar(255) DEFAULT NULL COMMENT '租赁物类型',
                                             `proj_indt_clas_code` varchar(6) DEFAULT NULL COMMENT '项目行业分类',
                                             `cust_name` varchar(512) DEFAULT NULL COMMENT '客户姓名',
                                             `cust_cert_num` varchar(255) DEFAULT NULL COMMENT '客户证件号码',
                                             `cust_scal_code` varchar(6) DEFAULT NULL COMMENT '客户规模',
                                             `fnl_rels` decimal(25,8) DEFAULT NULL COMMENT '融资租赁投放额',
                                             `wthd_prin` decimal(25,8) DEFAULT NULL COMMENT '收回本金',
                                             `rent_bal` decimal(25,8) DEFAULT NULL COMMENT '租金余额',
                                             `cmph_fin_cost` decimal(25,8) DEFAULT NULL COMMENT '综合融资成本',
                                             `udpn_situ_code` varchar(1000) DEFAULT NULL COMMENT '增信情况',
                                             `udpn` varchar(255) DEFAULT NULL COMMENT '增信方',
                                             `ovdu_rent` decimal(25,8) DEFAULT NULL COMMENT '逾期租金',
                                             `ovdu_days_code` varchar(32) DEFAULT NULL COMMENT '逾期天数',
                                             `ovdu_dsps_prog` varchar(255) DEFAULT NULL COMMENT '逾期处置情况',
                                             `np_flag` char(1) DEFAULT NULL COMMENT '是否纳入不良',
                                             `np_bal` decimal(25,8) DEFAULT NULL COMMENT '不良余额',
                                             `cust_vol` int(11) DEFAULT NULL COMMENT '客户数量',
                                             PRIMARY KEY (`id`),
                                             KEY `idx_report_instance_id` (`report_instance_id`,`deleted`),
                                             KEY `idx_reportinstanceid` (`report_instance_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='金融协会报送-主要业务清单表';

-- Create syntax for TABLE 'association_relation'
CREATE TABLE `association_relation` (
                                        `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键id',
                                        `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                        `create_by` bigint(20) DEFAULT NULL COMMENT '创建人id',
                                        `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                        `update_by` bigint(20) DEFAULT NULL COMMENT '更新人id',
                                        `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除，0-未删除',
                                        `row_num` int(11) NOT NULL COMMENT '行号',
                                        `report_instance_id` varchar(64) NOT NULL COMMENT '报表实例编号',
                                        `report_instance_period` varchar(24) NOT NULL COMMENT '报表实例周期',
                                        `batch_no` varchar(4) NOT NULL DEFAULT '' COMMENT '批次号',
                                        `version` varchar(128) DEFAULT NULL COMMENT '版本号',
                                        `op` varchar(16) NOT NULL COMMENT '操作标识',
                                        `report_time` datetime DEFAULT NULL COMMENT '上报时间',
                                        `write_time` timestamp NOT NULL COMMENT '写入数据库时间',
                                        `unif_soci_cred_code` varchar(32) NOT NULL COMMENT '企业统一社会信用代码',
                                        `onum` varchar(128) DEFAULT NULL COMMENT '序号',
                                        `relp_name` varchar(32) DEFAULT NULL COMMENT '关联方名称',
                                        `corp_shah_relp_flag` char(1) DEFAULT NULL COMMENT '是否为本公司股东关联方',
                                        `corp_shah_name` varchar(128) DEFAULT NULL COMMENT '本公司股东名称',
                                        `onbl_relp_leas_bal_srlp` decimal(25,8) DEFAULT NULL COMMENT '表内业务-关联方租赁余额_单一关联方',
                                        `onbl_onar_srlp` decimal(25,8) DEFAULT NULL COMMENT '表内业务-占净资产比例_单一关联方',
                                        `ofbl_guar_srlp` decimal(25,8) DEFAULT NULL COMMENT '表外业务-担保_单一关联方',
                                        `ofbl_oth_srlp` decimal(25,8) DEFAULT NULL COMMENT '表外业务-其他_单一关联方',
                                        `deit_qulf_sbim_srlp` decimal(25,8) DEFAULT NULL COMMENT '扣减项-合格质物_单一关联方',
                                        `deit_qulf_asue_srlp` decimal(25,8) DEFAULT NULL COMMENT '扣减项-合格保证_单一关联方',
                                        `deit_oth_srlp` decimal(25,8) DEFAULT NULL COMMENT '扣减项-其他_单一关联方',
                                        `cred_exps_srlp` decimal(25,8) DEFAULT NULL COMMENT '信用风险敞口_单一关联方',
                                        `grlp_name` varchar(128) DEFAULT NULL COMMENT '所在集团名称_关联方所在集团',
                                        `onbl_relp_leas_bal_grlp` decimal(25,8) DEFAULT NULL COMMENT '表内业务-关联方租赁余额_关联方所在集团',
                                        `onbl_onar_grlp` decimal(25,4) DEFAULT NULL COMMENT '表内业务-占净资产比例_关联方所在集团',
                                        `ofbl_guar_grlp` decimal(25,8) DEFAULT NULL COMMENT '表外业务-担保_关联方所在集团',
                                        `ofbl_oth_grlp` decimal(25,8) DEFAULT NULL COMMENT '表外业务-其他_关联方所在集团',
                                        `deit_qulf_sbim_grlp` decimal(25,8) DEFAULT NULL COMMENT '扣减项-合格质物_关联方所在集团',
                                        `deit_qulf_asue_grlp` decimal(25,8) DEFAULT NULL COMMENT '扣减项-合格保证_关联方所在集团',
                                        `deit_oth_grlp` decimal(25,8) DEFAULT NULL COMMENT '扣减项-其他_关联方所在集团',
                                        `cred_exps_grlp` decimal(25,8) DEFAULT NULL COMMENT '信用风险敞口_关联方所在集团',
                                        PRIMARY KEY (`id`),
                                        KEY `idx_reportinstanceid` (`report_instance_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='金融协会报送-关联方信息汇总表';

-- Create syntax for TABLE 'association_report'
CREATE TABLE `association_report` (
                                      `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键id',
                                      `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                      `create_by` bigint(20) DEFAULT NULL COMMENT '创建人id',
                                      `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                      `update_by` bigint(20) DEFAULT NULL COMMENT '更新人id',
                                      `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除，0-未删除',
                                      `report_category_code` varchar(20) NOT NULL DEFAULT '' COMMENT '报表分类编码',
                                      `report_category_name` varchar(100) NOT NULL DEFAULT '' COMMENT '报表分类名称',
                                      `is_retry` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否为重报数据，0-否，1-是',
                                      `report_instance_id` varchar(64) NOT NULL COMMENT '报表实例编号',
                                      `report_year` int(11) NOT NULL COMMENT '报表实例年份',
                                      `report_period_category` varchar(20) NOT NULL DEFAULT '' COMMENT '报表实例周期类型',
                                      `report_period` int(11) NOT NULL COMMENT '报表实例周期',
                                      `data_source` varchar(20) NOT NULL COMMENT '数据来源（创建方式）',
                                      `batch_no` varchar(4) NOT NULL COMMENT '批次号',
                                      `report_time` datetime DEFAULT NULL COMMENT '上报时间',
                                      `report_status` varchar(20) NOT NULL DEFAULT '' COMMENT '上报状态',
                                      PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='金融协会报送-主记录表';

-- Create syntax for TABLE 'association_report_sort'
CREATE TABLE `association_report_sort` (
                                           `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键id',
                                           `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                           `create_by` bigint(20) DEFAULT NULL COMMENT '创建人id',
                                           `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                           `update_by` bigint(20) DEFAULT NULL COMMENT '更新人id',
                                           `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除，0-未删除',
                                           `report_category_code` varchar(20) NOT NULL DEFAULT '' COMMENT '报表分类编码',
                                           `report_category_name` varchar(100) NOT NULL DEFAULT '' COMMENT '报表分类名称',
                                           `field_name` varchar(64) NOT NULL COMMENT '字段名称',
                                           `sort` int(11) NOT NULL COMMENT '字段排序 越小越前',
                                           PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='金融协会报送-上报文件字段排序';

-- Create syntax for TABLE 'association_top10_client_concentration'
CREATE TABLE `association_top10_client_concentration` (
